/**
 * Merges an afterEach extension's returned context into the accumulated context.
 *
 * Only the mutable fields are merged: `namedScores` (finite numbers only), `metadata`, and
 * `response.metadata`. The `success`, `score`, and `response.output` fields are never overridable
 * by extensions and are preserved from the accumulated context.
 */
function mergeAfterEachContext(
  prev: AfterEachExtensionHookContext,
  returned: Partial<AfterEachExtensionHookContext> | undefined,
): AfterEachExtensionHookContext {
  const returnedResult = returned?.result;

  // Shallow-merge namedScores, keeping only finite numeric values. Non-numeric values (strings,
  // null, arrays, objects), NaN, Infinity, and -Infinity are silently filtered out.
  const mergedNamedScores: Record<string, number> = { ...prev.result.namedScores };
  if (returnedResult?.namedScores && typeof returnedResult.namedScores === 'object') {
    for (const [key, value] of Object.entries(returnedResult.namedScores)) {
      if (Number.isFinite(value as number)) {
        mergedNamedScores[key] = value as number;
      }
    }
  }

  // Shallow-merge metadata, preserving existing keys not returned by the extension.
  const mergedMetadata = { ...prev.result.metadata };
  if (returnedResult?.metadata && typeof returnedResult.metadata === 'object') {
    Object.assign(mergedMetadata, returnedResult.metadata);
  }

  // Shallow-merge response.metadata, preserving all other fields on response (e.g. output).
  let mergedResponse = prev.result.response;
  const returnedResponseMetadata = returnedResult?.response?.metadata;
  if (returnedResponseMetadata && typeof returnedResponseMetadata === 'object') {
    mergedResponse = {
      ...(prev.result.response as EvaluateResult['response']),
      metadata: {
        ...(prev.result.response?.metadata ?? {}),
        ...returnedResponseMetadata,
      },
    } as EvaluateResult['response'];
  }

  return {
    test: prev.test,
    result: {
      ...prev.result,
      namedScores: mergedNamedScores,
      metadata: mergedMetadata,
      response: mergedResponse,
    },
  };
